const linhasModulos = r.resumo.map(x=>`<tr><th scope="row">${esc(x.modulo)}</th><td>${esc(x.dispositivo)}</td><td>${x.antes.n}</td><td>${n(x.antes.mediana)} → <strong>${n(x.depois.mediana)}</strong></td><td>${n(x.antes.p95)} → ${n(x.depois.p95)}</td><td>${n(x.antes.maximo)} → ${n(x.depois.maximo)}</td></tr>`).join('');
